// Monta o payload para o Gerador de Diagnóstico (Sonnet)
// Usa os dados já coletados e scorados na Fase 1
const lead = $input.item.json;

// Estrutura que o prompt do Gerador espera
const analistaOutput = {
  empresa: lead.business_name,
  score_capacidade: lead.score_capacidade,
  score_dor: lead.score_dor,
  score_encaixe: lead.score_encaixe,
  score_final: lead.score_final,
  grade: lead.score,
  rebaixado_por_capacidade: lead.rebaixado_por_capacidade,
  dores: (typeof lead.dores_estruturadas === 'string'
    ? JSON.parse(lead.dores_estruturadas || '[]')
    : lead.dores_estruturadas || []),
  gancho_de_abordagem: lead.gancho_de_abordagem,
  justificativa_encaixe: lead.justificativa_encaixe,
  dados_contexto: {
    cidade: lead.address_city,
    estado: lead.address_state,
    categoria: lead.google_category,
    nota_google: lead.google_rating,
    num_avaliacoes: lead.google_reviews_count,
    site: lead.website || 'não encontrado',
    cnpj_porte: lead.cnpj_porte,
    cnpj_situacao: lead.cnpj_situacao,
    anos_atividade: lead.cnpj_data_abertura
      ? Math.floor((Date.now() - new Date(lead.cnpj_data_abertura).getTime()) / (365.25 * 24 * 3600 * 1000))
      : null
  }
};

const systemPrompt = `Você é Consultor de Diagnóstico Digital da Hubimobi. Você analisou uma empresa e vai escrever um relatório de 1 página para o DONO dela ler.\n\nSeu tom: consultor que estudou o negócio dele, não vendedor. Você aponta problemas com evidência e mostra o que está em jogo — mas NÃO oferece serviço, NÃO cita preço, NÃO faz pitch. O objetivo é a pessoa pensar "esse cara entendeu meu negócio melhor que eu" e querer conversar.`;

const userPrompt = `DADOS (vindos da análise da Fase 1):\n${JSON.stringify(analistaOutput, null, 2)}\n\nOFERTA QUE A HUBIMOBI VENDE (use só para direcionar o "caminho", sem citar): ${lead.oferta_campanha || 'Presença Digital Completa'}\n\nREGRAS:\n- Português do Brasil, claro, sem jargão técnico que o dono não entenda.\n- Toda afirmação de problema precisa vir com a EVIDÊNCIA (o dado real).\n- O impacto financeiro é uma ESTIMATIVA com faixa, sempre rotulada como estimativa. Nunca invente número preciso.\n- Máximo 3 problemas — os mais fortes. Não liste tudo.\n- Termine apontando um CAMINHO, não um produto.\n\nRESPONDA APENAS COM ESTE JSON (sem markdown):\n{\n  "titulo": "Diagnóstico Digital — <nome da empresa>",\n  "resumo_executivo": "2-3 frases: o que a empresa faz bem e o principal ponto cego",\n  "ponto_forte": "1 coisa que eles JÁ fazem bem (gera confiança, mostra que você olhou de verdade)",\n  "problemas": [\n    {\n      "titulo": "frase curta",\n      "descricao": "o que está acontecendo, em linguagem do dono",\n      "evidencia": "o dado concreto que comprova",\n      "consequencia": "o que isso custa no dia a dia",\n      "impacto": "alto|medio|baixo"\n    }\n  ],\n  "impacto_estimado": {\n    "cenario_sem_acao": "o que continua acontecendo se nada mudar (faixa estimada)",\n    "cenario_com_acao": "o ganho plausível se resolver (faixa estimada, rotulada como estimativa)"\n  },\n  "caminho_sugerido": "a direção da solução em 2-3 frases, SEM citar produto ou preço",\n  "frase_de_fechamento": "1 frase que convida à conversa sem pressionar"\n}`;

return [{
  json: {
    ...lead,
    aiSystemPrompt: systemPrompt,
    aiUserPrompt: userPrompt
  }
}];

// Extrai JSON do diagnóstico da resposta do Sonnet
const apiResponse = $input.item.json;
const lead = $('Montar Prompt Diagnóstico').item.json;

let diag = {};
try {
  const rawText = apiResponse.content?.[0]?.text || '';
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('Sem JSON na resposta: ' + rawText.substring(0,100));
  diag = JSON.parse(jsonMatch[0]);
} catch (e) {
  diag = {
    titulo: `Diagnóstico Digital — ${lead.business_name}`,
    resumo_executivo: 'Erro ao gerar diagnóstico. Revisar manualmente.',
    ponto_forte: 'Dados insuficientes para avaliação.',
    problemas: [{ titulo: 'Erro de processamento', descricao: e.message, evidencia: 'N/A', consequencia: 'N/A', impacto: 'baixo' }],
    impacto_estimado: { cenario_sem_acao: 'N/A', cenario_com_acao: 'N/A' },
    caminho_sugerido: 'Revisar manualmente.',
    frase_de_fechamento: 'Entre em contato para discutir os resultados.'
  };
}

// Tokens e custo Sonnet (sonnet-4-6: $3/M input, $15/M output)
const promptTokens = apiResponse.usage?.input_tokens || 0;
const completionTokens = apiResponse.usage?.output_tokens || 0;
const costUsd = (promptTokens * 0.000003) + (completionTokens * 0.000015);

return [{
  json: {
    ...lead,
    diagnostico: diag,
    diagnostico_json: JSON.stringify(diag),
    aiPromptTokens: promptTokens,
    aiCompletionTokens: completionTokens,
    aiCostUsd: costUsd
  }
}];

// Preenche o template HTML com os dados do diagnóstico
// O template está inline para ser auto-contido
const lead = $input.item.json;
const d = lead.diagnostico;

// Data em PT-BR
const dataBR = new Date().toLocaleDateString('pt-BR', {
  day: '2-digit', month: 'long', year: 'numeric'
});

// Monta o bloco de problemas
const escapeHtml = s => (s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

const problemsHtml = (d.problemas || []).map(p => `
  <div class="problem-item impacto-${(p.impacto||'alto').toLowerCase()}">
    <div class="problem-title">${escapeHtml(p.titulo)}</div>
    <div class="problem-desc">${escapeHtml(p.descricao)}</div>
    <div class="problem-meta">
      <span class="meta-pill"><strong>Evidência:</strong> ${escapeHtml(p.evidencia)}</span>
      <span class="meta-pill"><strong>Consequência:</strong> ${escapeHtml(p.consequencia)}</span>
    </div>
  </div>
`).join('');

// Template HTML completo (baseado em sdr/templates/diagnostico.html)
let html = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><title>${escapeHtml(d.titulo)}</title><style>*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}body{font-family:'Segoe UI',Arial,sans-serif;font-size:11pt;color:#1a1a2e;background:#fff;line-height:1.55;width:210mm;min-height:297mm;padding:18mm 20mm 16mm 20mm}.header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #0056d2;padding-bottom:10px;margin-bottom:14px}.brand-name{font-size:20pt;font-weight:800;color:#0056d2;letter-spacing:2px;line-height:1}.brand-tagline{font-size:7.5pt;color:#6b7280;text-transform:uppercase;letter-spacing:1.5px;margin-top:2px}.doc-meta{text-align:right;font-size:8.5pt;color:#6b7280}.doc-meta .company-name{font-size:10.5pt;font-weight:700;color:#1a1a2e;margin-bottom:2px}.doc-title-bar{background:linear-gradient(135deg,#0056d2,#0ea5e9);color:white;padding:8px 14px;border-radius:6px;margin-bottom:14px}.doc-title-bar h1{font-size:12pt;font-weight:700}section{margin-bottom:12px}h2{font-size:9.5pt;font-weight:700;text-transform:uppercase;letter-spacing:1px;color:#0056d2;border-left:3px solid #0056d2;padding-left:7px;margin-bottom:7px}.executive-box{background:#f0f7ff;border:1px solid #bfdbfe;border-radius:6px;padding:10px 12px}.strong-point{display:flex;gap:6px;margin-bottom:6px;font-size:10pt}.check-icon{color:#16a34a;font-weight:800;flex-shrink:0}.resumo-text{font-size:10pt;color:#374151}.problem-item{border:1px solid #e5e7eb;border-left:4px solid #dc2626;border-radius:0 6px 6px 0;padding:8px 10px;margin-bottom:7px;page-break-inside:avoid}.problem-item.impacto-medio{border-left-color:#d97706}.problem-item.impacto-baixo{border-left-color:#6b7280}.problem-title{font-size:10.5pt;font-weight:700;color:#1a1a2e;margin-bottom:3px}.problem-desc{font-size:9.5pt;color:#374151;margin-bottom:4px}.problem-meta{display:flex;gap:14px;flex-wrap:wrap}.meta-pill{font-size:8.5pt;background:#f3f4f6;border-radius:4px;padding:2px 7px;color:#4b5563}.impact-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.impact-box{border-radius:6px;padding:8px 10px}.impact-box.bad{background:#fff1f2;border:1px solid #fecdd3}.impact-box.good{background:#f0fdf4;border:1px solid #bbf7d0}.impact-box h3{font-size:8.5pt;font-weight:700;text-transform:uppercase;letter-spacing:.5px;margin-bottom:4px}.impact-box.bad h3{color:#dc2626}.impact-box.good h3{color:#16a34a}.impact-box p{font-size:9.5pt;color:#374151}.path-box{background:#fafafa;border:1px solid #e5e7eb;border-radius:6px;padding:9px 12px}.path-text{font-size:10pt;color:#374151;margin-bottom:8px}.closing-quote{border-top:1px dashed #d1d5db;padding-top:7px;font-size:10.5pt;font-style:italic;color:#0056d2;font-weight:600;text-align:center}.footer{border-top:1px solid #e5e7eb;padding-top:8px;margin-top:14px;display:flex;justify-content:space-between;align-items:flex-end;font-size:7.5pt;color:#9ca3af}.footer-brand{font-weight:700;color:#6b7280}.disclaimer{max-width:320px;text-align:right;font-size:7pt;line-height:1.4}</style></head><body>
<div class="header">
  <div class="brand"><div class="brand-name">HUBIMOBI</div><div class="brand-tagline">Marketing &amp; Automação Digital</div></div>
  <div class="doc-meta"><div class="company-name">${escapeHtml(lead.business_name)}</div><div>${escapeHtml(lead.address_city||'')}${lead.address_state?'/'+lead.address_state:''}</div><div>${dataBR}</div></div>
</div>
<div class="doc-title-bar"><h1>${escapeHtml(d.titulo)}</h1></div>
<section><h2>Visão Geral</h2><div class="executive-box"><div class="strong-point"><span class="check-icon">✓</span><span><strong>O que está funcionando:</strong> ${escapeHtml(d.ponto_forte)}</span></div><p class="resumo-text">${escapeHtml(d.resumo_executivo)}</p></div></section>
<section><h2>Pontos Críticos Identificados</h2>${problemsHtml}</section>
<section><h2>O que está em jogo</h2><div class="impact-grid"><div class="impact-box bad"><h3>⚠ Sem ação</h3><p>${escapeHtml(d.impacto_estimado?.cenario_sem_acao||'')}</p></div><div class="impact-box good"><h3>✓ Com melhorias</h3><p>${escapeHtml(d.impacto_estimado?.cenario_com_acao||'')}</p></div></div></section>
<section><h2>Caminho Sugerido</h2><div class="path-box"><p class="path-text">${escapeHtml(d.caminho_sugerido)}</p><p class="closing-quote">${escapeHtml(d.frase_de_fechamento)}</p></div></section>
<div class="footer"><div><div class="footer-brand">HUBIMOBI</div><div>Diagnóstico confidencial · ${dataBR}</div></div><div class="disclaimer">As estimativas de impacto são projeções baseadas em dados de mercado e benchmarks do setor. Devem ser validadas com análise detalhada do negócio.</div></div>
</body></html>`;

// Converte HTML para binário para envio ao Gotenberg
const htmlBuf = Buffer.from(html, 'utf-8');

return [{
  json: { ...lead },
  binary: {
    htmlFile: {
      data: htmlBuf.toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html',
      fileExtension: 'html'
    }
  }
}];

const items = $input.all();
const summary = {
  mensagem: '✅ Fase 2 concluída — diagnósticos gerados e PDFs salvos!',
  timestamp: new Date().toISOString(),
  total_processados: items.length,
  proximos_passos: [
    '1. Execute no Supabase SQL Editor: SELECT * FROM sdr_diagnostico_review LIMIT 10',
    '2. Abra cada PDF pelo link diagnostico_pdf_url e revise o conteúdo',
    '3. Marque diagnostico_aprovado = true/false para cada lead revisado',
    '4. Meta: 8/10 aprovados sem ajuste antes de seguir para a Fase 3',
    '5. Consulte sdr/prompts/gerador-diagnostico.md para o gate de revisão completo'
  ],
  setup_gotenberg: 'Certifique-se que o Gotenberg está rodando: docker run --rm -p 3000:3000 gotenberg/gotenberg:8'
};
console.log(JSON.stringify(summary, null, 2));
return [{ json: summary }];
